mapper.sql:
(WITH RECURSIVE cte AS (SELECT c.id, c.parent_id FROM department_info AS c WHERE c.id = #{deptId}
UNION ALL
SELECT p.id, p.parent_id FROM department_info AS p INNER JOIN cte ON p.id = cte.parent_id) SELECT gp.permission AS permission FROM cte LEFT JOIN user_group ug ON cte.id = ug.dept_id LEFT JOIN group_privilege gp ON ug.group_id = gp.group_id WHERE gp.biz_type = 12 AND gp.is_del = 1 AND permission > 0 AND gp.target_id = #{databaseId})
